#define iterations 13
#define formuparam 0.53

#define volsteps 20
#define stepsize 0.1

#define zoom   0.800
#define tile   0.850
#define speed  0.000 

#define brightness 0.0015
#define darkmatter 0.300
#define distfading 0.730
#define saturation 0.850

#define NUM_OCTAVES 5

float rand(vec2 n) { 
    return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);
}
const float s3 = 1.7320508075688772;
const float i3 = 0.5773502691896258;

const mat2 tri2cart = mat2(1.0, 0.0, -0.5, 0.5 * s3);
const mat2 cart2tri = mat2(1.0, 0.0, i3, 2.0 * i3);

#define HASHSCALE1 .1031
#define HASHSCALE3 vec3(443.897, 441.423, 437.195)

float hash12(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * HASHSCALE1);
    p3 += dot(p3, p3.yzx + 19.19);
    return fract((p3.x + p3.y) * p3.z);
}

vec2 hash23(vec3 p3) {
    p3 = fract(p3 * HASHSCALE3);
    p3 += dot(p3, p3.yzx + 19.19);
    return fract((p3.xx + p3.yz) * p3.zy);
}

vec3 pal(float t) {
    const vec3 a = vec3(0.5);
    const vec3 b = vec3(0.5);
    const vec3 c = vec3(0.8, 0.8, 0.5);
    const vec3 d = vec3(0, 0.2, 0.5);
    return clamp(a + b * cos(6.28318 * (c * t + d)), 0.0, 1.0);
}

vec3 bary(vec2 v0, vec2 v1, vec2 v2) {
    float inv_denom = 1.0 / (v0.x * v1.y - v1.x * v0.y);
    float v = (v2.x * v1.y - v1.x * v2.y) * inv_denom;
    float w = (v0.x * v2.y - v2.x * v0.y) * inv_denom;
    float u = 1.0 - v - w;
    return vec3(u, v, w);
}

float dseg(vec2 xa, vec2 ba) {
    return length(xa - ba * clamp(dot(xa, ba) / dot(ba, ba), 0.0, 1.0));
}

vec2 randCircle(vec3 p) {
    vec2 rt = hash23(p);
    float r = sqrt(rt.x);
    float theta = 6.283185307179586 * rt.y;
    return r * vec2(cos(theta), sin(theta));
}

vec2 randCircleSpline(vec2 p, float t) {
    float t1 = floor(t);
    t -= t1;
    vec2 pa = randCircle(vec3(p, t1 - 1.0));
    vec2 p0 = randCircle(vec3(p, t1));
    vec2 p1 = randCircle(vec3(p, t1 + 1.0));
    vec2 pb = randCircle(vec3(p, t1 + 2.0));
    vec2 m0 = 0.5 * (p1 - pa);
    vec2 m1 = 0.5 * (pb - p0);
    vec2 c3 = 2.0 * p0 - 2.0 * p1 + m0 + m1;
    vec2 c2 = -3.0 * p0 + 3.0 * p1 - 2.0 * m0 - m1;
    vec2 c1 = m0;
    vec2 c0 = p0;
    return (((c3 * t + c2) * t + c1) * t + c0) * 0.8;
}

vec2 triPoint(vec2 p) {
    float t0 = hash12(p);
    return tri2cart * p + 0.45 * randCircleSpline(p, 0.15 * iTime + t0);
}

void tri_color(in vec2 p, in vec4 t0, in vec4 t1, in vec4 t2, in float scl, inout vec4 cw) {
    vec2 p0 = p - t0.xy;
    vec2 p10 = t1.xy - t0.xy;
    vec2 p20 = t2.xy - t0.xy;
    vec3 b = bary(p10, p20, p0);
    float d10 = dseg(p0, p10);
    float d20 = dseg(p0, p20);
    float d21 = dseg(p - t1.xy, t2.xy - t1.xy);
    float d = min(min(d10, d20), d21);
    d *= -sign(min(b.x, min(b.y, b.z)));
    if (d < 0.5 * scl) {
        vec2 tsum = t0.zw + t1.zw + t2.zw;
        vec3 h_tri = vec3(hash12(tsum + t0.zw), hash12(tsum + t1.zw), hash12(tsum + t2.zw));
        vec2 pctr = (t0.xy + t1.xy + t2.xy) / 3.0;
        float theta = 1.0 + 0.01 * iTime;
        vec2 dir = vec2(cos(theta), sin(theta));
        float grad_input = dot(pctr, dir) - sin(0.05 * iTime);
        float h0 = sin(0.7 * grad_input) * 0.5 + 0.5;
        h_tri = mix(vec3(h0), h_tri, 0.4);
        float h = dot(h_tri, b);
        vec3 c = pal(h);
        float w = smoothstep(0.5 * scl, -0.5 * scl, d);
        cw += vec4(w * c, w);
    }
}

vec2 psychedelicEffect(vec2 uv, float time) {
    uv -= 1.0;
    float angle = atan(uv.y, uv.x) + time;
    float radius = length(uv) * (4.0 + 0.1 * sin(time));
    uv = vec2(radius * cos(angle), radius * sin(angle));
    mat2 reflectMat = mat2(0.5, -0.5, 0.5, 0.5);
    uv = reflectMat * uv;
    uv = mat2(cos(time), -sin(time), sin(time), cos(time)) * uv;
    uv += 0.5;
    return uv;
}

float noise(vec2 p){
    vec2 ip = floor(p);
    vec2 u = fract(p);
    u = u*u*(3.0-2.0*u);

    float res = mix(
        mix(rand(ip),rand(ip+vec2(1.0,0.0)),u.x),
        mix(rand(ip+vec2(0.0,1.0)),rand(ip+vec2(1.0,1.0)),u.x),u.y);
    return res*res;
}

float fbm(vec2 x) {
    float v = 0.0;
    float a = 0.5;
    vec2 shift = vec2(100);    
    mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.50));
    for (int i = 0; i < NUM_OCTAVES; ++i) {
        v += a * noise(x);
        x = rot * x * 2.0 + shift;
        a *= 0.5;
    }
    return v;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	//get coords and direction
	vec2 uv=fragCoord.xy/iResolution.xy-.5;
	uv.y*=iResolution.y/iResolution.x;
	vec3 dir=vec3(uv*zoom,1.);
	float time=iTime*speed+.25;
 float scl = 4.1 / iResolution.y;
    vec2 p2 = (fragCoord - 0.5 * iResolution.xy) * scl;
    p2 = psychedelicEffect(p2, iTime * 0.1);
    vec2 tfloor = floor(cart2tri * p2 + 0.5);
    vec2 pts[10];
    for (int i = 0; i < 3; ++i) for (int j = 0; j < 3; ++j) pts[3 * i + j] = triPoint(tfloor + vec2(i - 1, j - 1));
    vec4 cw = vec4(0);
    for (int i = 0; i < 2; ++i) for (int j = 0; j < 2; ++j) {
        vec4 t00 = vec4(pts[3 * i + j], tfloor + vec2(i - 1, j - 1));
        vec4 t10 = vec4(pts[3 * i + j + 3], tfloor + vec2(i, j - 1));
        vec4 t01 = vec4(pts[3 * i + j + 1], tfloor + vec2(i - 1, j));
        vec4 t11 = vec4(pts[3 * i + j + 4], tfloor + vec2(i, j));
        tri_color(p2, t00, t10, t11, scl, cw);
        tri_color(p2, t00, t11, t01, scl, cw);
    }
	 vec2 shake = vec2(sin(iTime * 1.5) * 0.01, cos(iTime * 2.7) * 0.01);

    vec4 o =fragColor;

    vec2 p = ((fragCoord.xy + shake * iResolution.xy) - iResolution.xy * 0.5) / iResolution.y * mat2(0.0, -4.0, -3.0, 8.0);
    vec2 v=fragCoord;
    o = vec4(0.0);
    p.xy*=mat2(cos(iTime),sin(iTime),-sin(iTime), cos(iTime));
    float f = 3.0 + fbm(p + vec2(iTime * 0.0, 0.0)); 

    for(float i = 0.0; i++ < 50.0;)
    {
        v = p + cos(i * i + (iTime*0. + p.x * 0.1) * 0.03 + i * vec2(11.0, 9.0)) * 5.0 + vec2(sin(iTime * 4.0 + i) * 0.005, cos(iTime * 4.5 - i) * 0.005);

        float tailNoise = fbm(v + vec2(iTime, i)) * (1.0 - (i / 50.0)); 
        vec4 currentContribution = (cos(sin(i) * vec4(4.0, 2.0, 3.0, 1.0)) + 1.0) * exp(sin(i * i + iTime)) / length(max(v, vec2(v.x * f * 0.02, v.y)));


        float thinnessFactor = smoothstep(0.0, 1.0, i / 50.0) ;
        o += currentContribution * (1.0 + tailNoise * 2.0) * thinnessFactor;
    }

    o = tanh(pow(o / 1e2, vec4(1.5)));




	vec3 from=vec3(1.,.5,0.5);
	from+=vec3(time*2.,time,-2.);

	//volumetric rendering
	float s=0.1,fade=1.;
	vec3 v2=vec3(0.);
	for (int r=0; r<volsteps; r++) {
		vec3 p=from+s*dir*.5*cw.xyz;;
		p = abs(vec3(tile)-mod(p,vec3(tile*2.))); // tiling fold
		float pa,a=pa=0.;
		for (int i=0; i<iterations; i++) { 
			p=abs(p)/dot(p,p)-formuparam;
            p.xy*=mat2(cos(iTime*0.02),sin(iTime*0.02),-sin(iTime*0.02),cos(iTime*0.02));// the magic formula
			a+=abs(length(p)-pa); // absolute sum of average change
			pa=length(p);
		}
		float dm=max(0.,darkmatter-a*a*.001); //dark matter
		a*=a*a; // add contrast
		if (r>6) fade*=1.2-dm; // dark matter, don't render near
		//v+=vec3(dm,dm*.5,0.);
		v2+=fade;
		v2+=vec3(s,s*s,s*s*s*s)*a*brightness*fade; // coloring based on distance
		fade*=distfading; // distance fading
		s+=stepsize;
	}
	v2=mix(vec3(length(v2)),v2,saturation); //color adjust
	fragColor = vec4(v2*.04*o.xyz*6.,1.);	

}
